ALTER TYPE "ReplyClassification" ADD VALUE IF NOT EXISTS 'ASKING_DETAILS';
ALTER TABLE "Mailbox" ADD COLUMN "imapLastUid" INTEGER NOT NULL DEFAULT 0;
